/**async handleSetPulseTime(deviceId: string, deciseconds: number): Promise<void> {
  // 🔍 CRITICAL FIX: Lookup device object first
  const device = deviceService.getDevice(deviceId);
  if (!device) {
    this.showError('Device not found');
