      transform: translateX(4px);
    }

    .feature-icon {
      font-size: 0.7rem;
      transition: transform 0.2s ease;
    }

    .feature-item:hover .feature-icon {
      transform: scale(1.2);
    }

    .feature-icon.enabled {
      color: #10b981;
    }

    .feature-icon.disabled {
      color: #64748b;
    }

    /* Panel Actions */
    .panel-actions {
      padding: 20px 24px;
      display: flex;
      gap: 12px;
    }

    .btn {
      flex: 1;
      padding: 12px 16px;
      border: none;
      border-radius: 10px;
      font-size: 0.85rem;
      font-weight: 700;
      cursor: pointer;
      transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      font-family: inherit;
      position: relative;
      overflow: hidden;
      letter-spacing: 0.3px;
    }

    .btn::before {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, rgba(255, 255, 255, 0.2) 0%, transparent 50%, rgba(255, 255, 255, 0.2) 100%);
      transform: translateX(-100%) skewX(-15deg);
      transition: transform 0.6s;
    }

    .btn:hover::before {
      transform: translateX(100%) skewX(-15deg);
    }

    .btn-upgrade {
      background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);
      color: white;
      box-shadow: 0 4px 12px rgba(99, 102, 241, 0.3);
      border: 1px solid rgba(99, 102, 241, 0.4);
    }

    .btn-upgrade:hover {
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(99, 102, 241, 0.4);
    }

    .btn-manage {
      background: rgba(15, 23, 42, 0.6);
      border: 1px solid rgba(148, 163, 184, 0.3);
      color: #cbd5e1;
    }

    .btn-manage:hover {
      background: rgba(59, 130, 246, 0.1);
      border-color: #3b82f6;
      color: #3b82f6;
      transform: translateY(-2px);
      box-shadow: 0 4px 12px rgba(59, 130, 246, 0.2);
    }

    /* Loading State */
    .widget-trigger:disabled {
      opacity: 0.6;
      cursor: not-allowed;
      transform: none !important;
    }

    .widget-trigger:disabled:hover::before {
      left: -100%;
    }

    /* Animation for dropdown items */
    .usage-item,
    .feature-item {
      animation: slideIn 0.2s ease-out backwards;
    }

    .usage-item:nth-child(1) { animation-delay: 0.05s; }
    .usage-item:nth-child(2) { animation-delay: 0.1s; }
    .usage-item:nth-child(3) { animation-delay: 0.15s; }
    .feature-item:nth-child(1) { animation-delay: 0.1s; }
    .feature-item:nth-child(2) { animation-delay: 0.15s; }
    .feature-item:nth-child(3) { animation-delay: 0.2s; }
    .feature-item:nth-child(4) { animation-delay: 0.25s; }
    .feature-item:nth-child(5) { animation-delay: 0.3s; }
    .feature-item:nth-child(6) { animation-delay: 0.35s; }

    @keyframes slideIn {
      from {
        opacity: 0;
        transform: translateX(10px);
      }
      to {
        opacity: 1;
        transform: translateX(0);
      }
    }

    /* Responsive Design */
    @media (max-width: 768px) {
      .dropdown-panel {
        min-width: 300px;
        max-width: 90vw;
        right: -10px;
      }

      .features-list {
        grid-template-columns: 1fr;
      }

      .panel-actions {
        flex-direction: column;
      }

      .widget-trigger {
        min-width: 120px;
        padding: 8px 14px;
      }

      .tier-name {
        font-size: 0.85rem;
      }
    }

    @media (max-width: 480px) {
      .dropdown-panel {
        min-width: 280px;
        right: -20px;
      }

      .panel-header,
      .usage-section,
      .features-section,
      .panel-actions {
        padding: 16px 20px;
      }

      .widget-trigger {
        min-width: 110px;
      }

      .tier-name {
        display: none;
      }

      .tier-badge {
        gap: 6px;
      }
    }

    /* Accessibility */
    .widget-trigger:focus-visible {
      outline: 2px solid #3b82f6;
      outline-offset: 2px;
    }

    .btn:focus-visible {
      outline: 2px solid #3b82f6;
      outline-offset: 2px;
    }

    /* High Contrast Mode Support */
    @media (prefers-contrast: high) {
      .widget-trigger {
        border-width: 2px;
      }

      .dropdown-panel {
        border-width: 2px;
      }

      .btn {
        border-width: 2px;
      }
    }

    /* Reduced Motion Support */
    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }
  `;

