    }

    .emergency-panel {
      padding: 20px;
      background: var(--error-bg, #ffe0e0);
      border: 2px solid var(--error, #ff0000);
      border-radius: 8px;
      box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    }

    h3 {
      margin: 0 0 16px 0;
      font-size: 20px;
      color: var(--error, #ff0000);
    }

    .emergency-stop {
      width: 100%;
      padding: 16px;
      font-size: 18px;
      font-weight: bold;
      background: #ff0000;
      color: white;
      border: none;
      border-radius: 8px;
      cursor: pointer;
      margin-bottom: 12px;
      transition: background 0.2s;
    }

    .emergency-stop:hover:not(:disabled) {
      background: #cc0000;
    }

    .emergency-stop.active {
      background: #990000;
      animation: pulse 1.5s infinite;
      cursor: pointer;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.8; transform: scale(0.98); }
    }

    .emergency-active {
      margin-bottom: 16px;
    }

    .emergency-message {
      margin: 12px 0 0 0;
      padding: 12px;
      background: rgba(255, 255, 255, 0.9);
      border-radius: 4px;
      color: #333;
      font-weight: 500;
    }

    .pause-commands {
      width: 100%;
      padding: 12px;
      font-size: 16px;
      font-weight: 500;
      background: #ff8800;
      color: white;
      border: none;
      border-radius: 8px;
      cursor: pointer;
      margin-bottom: 12px;
      transition: background 0.2s;
    }

    .pause-commands:hover:not(:disabled) {
      background: #e67700;
    }

    .pause-commands:disabled {
      opacity: 0.6;
      cursor: not-allowed;
    }

    .pause-commands.active {
      background: #cc6600;
    }

    .quick-actions {
      display: flex;
      gap: 8px;
      margin-bottom: 16px;
    }

    .quick-action {
      flex: 1;
      padding: 10px;
      font-size: 14px;
      font-weight: 500;
      background: #4a90e2;
      color: white;
      border: none;
      border-radius: 6px;
      cursor: pointer;
      transition: background 0.2s;
    }

    .quick-action:hover {
      background: #357abd;
    }

    .status-section {
      margin-top: 16px;
      padding-top: 16px;
      border-top: 1px solid rgba(0, 0, 0, 0.1);
    }

    .status-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 12px;
    }

    .status-item {
      display: flex;
      flex-direction: column;
      padding: 12px;
      background: rgba(255, 255, 255, 0.8);
      border-radius: 6px;
    }

    .status-label {
      font-size: 12px;
      color: #666;
      margin-bottom: 4px;
      font-weight: 500;
    }

    .status-value {
      font-size: 18px;
      font-weight: bold;
      color: #333;
    }

    .status-value.active {
      color: #4a90e2;
    }

    .status-value.warning {
      color: #ff8800;
    }

    .status-value.success {
      color: #00aa00;
    }

    .status-value.error {
      color: #ff0000;
    }

    .help-text {
      margin-top: 16px;
      padding: 12px;
      background: rgba(255, 255, 255, 0.6);
      border-radius: 6px;
      font-size: 13px;
      color: #555;
    }

    .help-text p {
      margin: 6px 0;
    }

    .help-text strong {
      color: #333;
    }

    /* Compact Mode */
    .emergency-compact {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .emergency-button {
      padding: 8px 16px;
      font-size: 16px;
      font-weight: bold;
      background: #ff0000;
      color: white;
      border: none;
      border-radius: 6px;
      cursor: pointer;
      transition: background 0.2s;
    }

    .emergency-button:hover {
      background: #cc0000;
    }

    .emergency-button.active {
      background: #990000;
      animation: pulse 1.5s infinite;
    }

    .pause-indicator {
      padding: 6px 12px;
      background: #ff8800;
      color: white;
      border-radius: 4px;
      font-size: 14px;
      font-weight: 500;
    }
  `;

@state() private settings: TelegramSettings = {
    enabled: false,
    botToken: '',
    chatId: '',
    defaultCooldownMinutes: 5,
    quietHoursEnabled: false,
    groupAlerts: false,
    groupAlertDelay: 10
  };

